SINA_SMART["parasito-bilharzia"] = {"lecture":"parasito-bilharzia","title":"Schistosomiasis (bilharzia)","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"parasito-bilharzia:e0","text":"Schistosomes: blood flukes with separate sexes in venous plexuses.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e1","text":"'Bare feet' disease: cercariae penetrate skin in fresh water.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e2","text":"S. haematobium: urogenital (Bulinus); S. mansoni: intestinal (Biomphalaria).","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e3","text":"Morocco: only S. haematobium, south of the Atlas; dams spread it.","topic":"Epidemiology and Morocco","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e4","text":"Eggs: haematobium terminal spine; mansoni lateral spine.","topic":"Parasite and cycle","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e5","text":"Granulomas around trapped eggs → fibrosis.","topic":"Parasite and cycle","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e10","text":"Serology from 15-30 days.","topic":"Clinical phases","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e6","text":"Invasion: fever, allergy, eosinophilia; stool/urine negative; serology.","topic":"Clinical phases","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e7","text":"Haematobium: terminal haematuria, bladder fibrosis, bladder cancer.","topic":"Clinical phases","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e8","text":"Mansoni: liver fibrosis, portal hypertension.","topic":"Clinical phases","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e11","text":"Praziquantel 40 mg/kg in one day (60 for japonicum).","topic":"Diagnosis and treatment","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-bilharzia:e9","text":"Eggs detectable 6-8 weeks after infection; urine at noon after exercise.","topic":"Diagnosis and treatment","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"s3c5wr":"a","y7zwwo":"a","1jaws6s":"a","1az9r2p":"a","qh386z":"a","9inyyu":"a","zkipd7":"a","1wl1m81":"a","nw0b06":"a","psrpey":"a","1qzoaii":"a","chn9pt":"a","1np3mon":"a","ropstg":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"parasito-bilharzia:e0":{"s":0,"u":["Schistosomes: blood flukes with separate sexes in venous plexuses.","Schistosomiasis (bilharzia) is caused by blood flukes (schistosomes) : separate-sex worms living in the venous plexuses ."],"dp":[]},"parasito-bilharzia:e1":{"s":0,"u":["'Bare feet' disease: cercariae penetrate skin in fresh water.","A disease of 'bare feet' and fresh water, with heavy morbidity, it spreads with irrigation and dams."],"dp":[{"h":"Why dams can cause schistosomiasis","t":"Dams and irrigation channels create still, warm fresh water where Bulinus and Biomphalaria snails thrive, in places that were previously arid. When people wash, bathe or farm in that water and there are no latrines, the cycle closes quickly. The Ouarzazate outbreak in Morocco is a textbook example of development creating a parasitic disease. Source: the lecture's Morocco history slide."}]},"parasito-bilharzia:e2":{"s":0,"u":["S. haematobium: urogenital (Bulinus); S. mansoni: intestinal (Biomphalaria).","Four species infect humans: S. haematobium (urogenital; snail Bulinus ), S. mansoni (intestinal; Biomphalaria ), S. japonicum (intestinal, with vascular complications; Oncomelania ), S. intercalatum (rectal, genital; Bulinus )."],"dp":[]},"parasito-bilharzia:e3":{"s":1,"u":["Morocco: only S. haematobium, south of the Atlas; dams spread it.","In Morocco only urogenital schistosomiasis ( S. haematobium ) exists: first cases 1927, south of the Atlas (Errachidia, Zagora, Agadir); the Ouarzazate dam extended irrigation and caused an outbreak; foci north of the Atlas (Marrakech, Beni Mellal, Kenitra, Tangier...)."],"dp":[]},"parasito-bilharzia:e4":{"s":2,"u":["Eggs: haematobium terminal spine; mansoni lateral spine.","Eggs : embryonated, spined : S. haematobium oval with a large terminal spine ; S. mansoni oval with a large lateral spine ; S. intercalatum rhomboid, terminal spine; S. japonicum round, small lateral spine."],"dp":[]},"parasito-bilharzia:e5":{"s":2,"u":["Granulomas around trapped eggs → fibrosis.","Some eggs cross into the bladder or bowel lumen and are excreted; others embolise to the liver, lungs and elsewhere, forming granulomas (epithelioid-giant cell, centred on egg debris) and fibrosis."],"dp":[{"h":"Why the worms themselves do little harm","t":"Adult schistosomes coat themselves with host molecules and live for years in veins without triggering inflammation. The damage comes from their eggs: many never reach the bladder or bowel lumen and lodge in tissues, where each one triggers a granuloma. Thousands of granulomas scar the bladder wall or the liver's portal spaces, causing haematuria, cancer risk or portal hypertension. Source: the lecture's cycle and granuloma slides."}]},"parasito-bilharzia:e10":{"s":3,"u":["Serology from 15-30 days.","Penetration : within 30 min, lasting up to 2 days: cercarial dermatitis (papules, vesicles, itch), often discreet."],"dp":[]},"parasito-bilharzia:e6":{"s":3,"u":["Invasion: fever, allergy, eosinophilia; stool/urine negative; serology.","Invasion (5-6 weeks): irregular fever, allergic signs (cough, asthma-like dyspnoea) , fleeting oedema, headache, myalgia, diarrhoea, hepatosplenomegaly; very high eosinophilia ; stool and urine exams are still negative; diagnosis by history and serology."],"dp":[]},"parasito-bilharzia:e7":{"s":3,"u":["Haematobium: terminal haematuria, bladder fibrosis, bladder cancer.","State phase (egg laying): S. haematobium : terminal haematuria , cystitis, dysuria, frequency, cloudy bloody urine; genital fibrosis and sterility; bladder carcinoma ."],"dp":[]},"parasito-bilharzia:e8":{"s":3,"u":["Mansoni: liver fibrosis, portal hypertension.","S. mansoni/japonicum : diarrhoea or bilharzial dysentery, abdominal pain, hepatosplenomegaly, liver fibrosis and portal hypertension ."],"dp":[]},"parasito-bilharzia:e11":{"s":4,"u":["Praziquantel 40 mg/kg in one day (60 for japonicum).","Treatment : praziquantel , single-day course: 40 mg/kg ( haematobium, mansoni, intercalatum ) or 60 mg/kg ( japonicum ); very well tolerated, used for mass treatment."],"dp":[]},"parasito-bilharzia:e9":{"s":4,"u":["Eggs detectable 6-8 weeks after infection; urine at noon after exercise.","Parasitology (positive only 6-8 weeks after infection, impossible in invasion): urine for S. haematobium (circadian excretion peaking around noon , increased by exercise: collect urine after effort, end of micturition); stool with Kato (eggs per gram); live egg (moving miracidium, hatching test) = active disease, dead or calcified egg = old infection; rectal biopsy (Ziehl shell: negative for S. haematobium , positive for others), bladder biopsy."],"dp":[]}},"meta":{"s3c5wr":{"a":"recall","vg":"parasito-bilharzia:e0/recall/1"},"y7zwwo":{"a":"recall","vg":"parasito-bilharzia:e1/recall/1"},"1jaws6s":{"a":"recall","vg":"parasito-bilharzia:e3/recall/1"},"1az9r2p":{"a":"recall","vg":"parasito-bilharzia:e2/recall/1"},"qh386z":{"a":"recall","vg":"parasito-bilharzia:e4/recall/1"},"9inyyu":{"a":"recall","vg":"parasito-bilharzia:e5/recall/1"},"zkipd7":{"a":"recall","vg":"parasito-bilharzia:e6/recall/1"},"1wl1m81":{"a":"recall","vg":"parasito-bilharzia:e7/recall/1"},"nw0b06":{"a":"relationship","vg":"parasito-bilharzia:e8/relationship/1"},"psrpey":{"a":"recall","vg":"parasito-bilharzia:e9/recall/1"},"1qzoaii":{"a":"recall","vg":"parasito-bilharzia:e9/recall/2"},"chn9pt":{"a":"recall","vg":"parasito-bilharzia:e9/recall/3"},"1np3mon":{"a":"recall","vg":"parasito-bilharzia:e6/recall/2"},"ropstg":{"a":"recall","vg":"parasito-bilharzia:e11/recall/1"}},"explRev":"e4e2e29d2f19"};
